def is_prime(k):
    if k < 2:
        return False
    for i in range(2, int(k**0.5) + 1):
        if k % i == 0:
            return False
    return True

factors = [(1, 735), (3, 245), (5, 147), (7, 105), (15, 49), (21, 35)]
solutions = []

for A, B in factors:
    # Check parity: A and B must both be odd (since 735 is odd)
    if (A + B) % 2 != 0:
        continue

    p = (B - A) // 2
    q = (A + B) // 2

    if is_prime(p) and is_prime(q):
        solutions.append((p, q, A, B))

print("Solutions (p, q, A, B):", solutions)

import math

def tau(n):
    if n <= 0:
        return 0
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

